package com.example.saasguide.communication.application;
import static org.assertj.core.api.Assertions.assertThat; import com.example.saasguide.communication.application.config.EligibilityClientProperties; import org.junit.jupiter.api.Test; import org.springframework.boot.context.properties.bind.Binder; import org.springframework.boot.env.YamlPropertySourceLoader; import org.springframework.core.env.MutablePropertySources; import org.springframework.core.io.ClassPathResource;
class ProfileConfigurationTest { @Test void profilesLoad()throws Exception{assertThat(load("application-application-timeout.yml").readTimeout().getSeconds()).isEqualTo(2);assertThat(load("application-mesh-timeout.yml").readTimeout().getSeconds()).isEqualTo(10);} private EligibilityClientProperties load(String name)throws Exception{var sources=new MutablePropertySources();for(var source:new YamlPropertySourceLoader().load(name,new ClassPathResource(name)))sources.addLast(source);return new Binder(ConfigurationPropertySources.from(sources)).bind("clients.eligibility",EligibilityClientProperties.class).orElseThrow();} }
